try{var t=localStorage.getItem("naaic-theme");if(t==="light"||t==="dark")document.documentElement.setAttribute("data-theme",t)}catch(e){}
document.addEventListener("DOMContentLoaded",function(){var b=document.getElementById("thm"),R=document.documentElement,mq=matchMedia("(prefers-color-scheme:dark)");function cur(){return R.getAttribute("data-theme")||(mq.matches?"dark":"light")}function lab(){var t=cur()==="dark"?"Switch to light mode":"Switch to dark mode";b.setAttribute("aria-label",t);b.title=t}b.addEventListener("click",function(){var n=cur()==="dark"?"light":"dark";R.setAttribute("data-theme",n);try{localStorage.setItem("naaic-theme",n)}catch(e){}lab()});mq.addEventListener("change",lab);lab();
var cs=document.querySelectorAll(".chip");if(!cs.length)return;function ap(k){cs.forEach(function(c){c.setAttribute("aria-pressed",c.dataset.k===k?"true":"false")});var items=document.querySelectorAll(".it"),n=0;items.forEach(function(i){var on=k==="all"||i.dataset.k===k;i.hidden=!on;if(on)n++});document.querySelectorAll(".mo").forEach(function(h){var u=h.nextElementSibling,v=u&&u.querySelector(".it:not([hidden])");h.hidden=!v;if(u)u.hidden=!v});var m=document.getElementById("cnt");if(m)m.textContent=n+" item"+(n===1?"":"s")}
var q=new URLSearchParams(location.search).get("kind")||"all",ok=false;cs.forEach(function(c){if(c.dataset.k===q)ok=true});ap(ok?q:"all");cs.forEach(function(c){c.addEventListener("click",function(){var k=c.dataset.k;ap(k);try{var u=new URL(location.href);if(k==="all")u.searchParams.delete("kind");else u.searchParams.set("kind",k);history.replaceState(null,"",u)}catch(e){}})})});
